from pathlib import Path

path = Path('lib/screens/canonical_settings_screen.dart')
text = path.read_text(encoding='utf-8')

if "import '../services/auth_service.dart';" not in text:
    marker = "import '../providers/text_scale_provider.dart';\n"
    if marker not in text:
        raise SystemExit('settings import marker not found')
    text = text.replace(marker, marker + "import '../services/auth_service.dart';\n", 1)

old_stream = """    return StreamBuilder<User?>(\n      stream: FirebaseAuth.instance.userChanges(),\n      initialData: FirebaseAuth.instance.currentUser,\n"""
new_stream = """    return StreamBuilder<User?>(\n      stream: AuthService.instance.authStateChanges,\n      initialData: AuthService.instance.currentUser,\n"""
if old_stream not in text:
    raise SystemExit('premium auth stream not found')
text = text.replace(old_stream, new_stream, 1)

old_account = """                        child: user == null\n                            ? Icon(\n                                Icons.person_outline_rounded,\n                                color: theme.colorScheme.primary,\n                                size: 22,\n                              )\n                            : Icon(\n                                Icons.person_rounded,\n                                color: theme.colorScheme.primary,\n                                size: 22,\n                              ),\n"""
new_account = """                        child: Builder(\n                          builder: (context) {\n                            final photoUrl = user?.photoURL?.trim();\n                            final hasPhoto =\n                                user != null && photoUrl != null && photoUrl.isNotEmpty;\n                            return Material(\n                              color: Colors.transparent,\n                              child: InkWell(\n                                onTap: () async {\n                                  if (user == null) {\n                                    await Navigator.of(context).push(\n                                      MaterialPageRoute<void>(\n                                        builder: (_) => const GoogleLoginScreen(),\n                                      ),\n                                    );\n                                    return;\n                                  }\n                                  await showModalBottomSheet<void>(\n                                    context: context,\n                                    showDragHandle: true,\n                                    builder: (sheetContext) {\n                                      return SafeArea(\n                                        child: Padding(\n                                          padding: const EdgeInsets.fromLTRB(20, 8, 20, 24),\n                                          child: Column(\n                                            mainAxisSize: MainAxisSize.min,\n                                            children: [\n                                              CircleAvatar(\n                                                radius: 34,\n                                                backgroundColor: AppColors.seaBlue.withValues(alpha: .10),\n                                                backgroundImage: hasPhoto\n                                                    ? NetworkImage(photoUrl!)\n                                                    : null,\n                                                child: hasPhoto\n                                                    ? null\n                                                    : const Icon(Icons.account_circle_rounded, size: 46),\n                                              ),\n                                              const SizedBox(height: 12),\n                                              Text(\n                                                user.displayName?.trim().isNotEmpty == true\n                                                    ? user.displayName!\n                                                    : 'NurVerse User',\n                                                style: theme.textTheme.titleLarge?.copyWith(\n                                                  fontWeight: FontWeight.w800,\n                                                ),\n                                                textAlign: TextAlign.center,\n                                              ),\n                                              if (user.email?.isNotEmpty == true) ...[\n                                                const SizedBox(height: 4),\n                                                Text(\n                                                  user.email!,\n                                                  style: theme.textTheme.bodyMedium?.copyWith(\n                                                    color: theme.textTheme.bodyMedium?.color\n                                                        ?.withValues(alpha: .70),\n                                                  ),\n                                                  textAlign: TextAlign.center,\n                                                ),\n                                              ],\n                                              const SizedBox(height: 20),\n                                              SizedBox(\n                                                width: double.infinity,\n                                                child: OutlinedButton.icon(\n                                                  onPressed: () async {\n                                                    Navigator.of(sheetContext).pop();\n                                                    await AuthService.instance.signOut();\n                                                  },\n                                                  icon: const Icon(Icons.logout_rounded),\n                                                  label: Text(\n                                                    languageCode == 'en' ? 'Logout' : 'লগআউট',\n                                                  ),\n                                                ),\n                                              ),\n                                            ],\n                                          ),\n                                        ),\n                                      );\n                                    },\n                                  );\n                                },\n                                borderRadius: BorderRadius.circular(14),\n                                child: SizedBox(\n                                  width: 42,\n                                  height: 42,\n                                  child: hasPhoto\n                                      ? ClipRRect(\n                                          borderRadius: BorderRadius.circular(13),\n                                          child: Image.network(\n                                            photoUrl!,\n                                            width: 42,\n                                            height: 42,\n                                            fit: BoxFit.cover,\n                                            errorBuilder: (_, __, ___) => Icon(\n                                              Icons.person_rounded,\n                                              color: theme.colorScheme.primary,\n                                              size: 22,\n                                            ),\n                                          ),\n                                        )\n                                      : user != null\n                                          ? Icon(\n                                              Icons.person_rounded,\n                                              color: theme.colorScheme.primary,\n                                              size: 22,\n                                            )\n                                          : const Center(\n                                              child: Text(\n                                                'G',\n                                                style: TextStyle(\n                                                  fontSize: 21,\n                                                  fontWeight: FontWeight.w900,\n                                                  color: AppColors.seaBlue,\n                                                ),\n                                              ),\n                                            ),\n                                ),\n                              ),\n                            );\n                          },\n                        ),\n"""
if old_account not in text:
    raise SystemExit('premium account button not found')
text = text.replace(old_account, new_account, 1)

path.write_text(text, encoding='utf-8')
print('premium account v2 patch applied - retry trigger')
